// ===== C02 Anti-Cheat : protège la progression et le multijoueur (dissuasion côté client, validation côté hôte) =====
const ACG=(()=>{
  const NAME='C02 Anti-Cheat',VER='1.2';
  const SALT=String.fromCharCode(67,48,50,45,65,67,47,102,114,111,115,116,45,55,51,49,57,45,115,105,103);
  const h53=(str,seed)=>{let h1=0xdeadbeef^seed,h2=0x41c6ce57^seed;for(let i=0;i<str.length;i++){const c=str.charCodeAt(i);h1=Math.imul(h1^c,2654435761);h2=Math.imul(h2^c,1597334677)}
    h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909);h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909);return(4294967296*(2097151&h2)+(h1>>>0)).toString(36)};
  const sign=s=>h53(SALT+s,17)+h53(s+SALT,91)+h53(s.length+SALT+s,5);
  const st={log:[],sig:'new',plaus:'ok',clock:'ok',rt:'ok',code:'ok',data:'ok',vault:'off',cheat:false,tampered:false,mpBlock:'',runReason:''};
  const note=m=>{st.log.push({t:Date.now(),m});if(st.log.length>40) st.log.shift();try{console.warn('['+NAME+'] '+m)}catch(e){}};
  const canon=s=>{
    const o=s.own||{},up=s.up||{},bo=s.boost||{},mc=s.mapClear||{},so=s.skinsOwned||{},mw=s.mapWaves||{},dl=s.daily||{};
    const flat=x=>{const r=[];for(const k of Object.keys(x||{}).sort()){const v=x[k];r.push(k+(v&&typeof v==='object'?'{'+flat(v)+'}':':'+v))}return r.join(';')};
    return[+s.bank||0,+s.xp||0,Object.keys(o).filter(k=>o[k]).sort().join(','),s.hpLvl|0,s.dmgLvl|0,Object.keys(up).sort().map(k=>k+':'+((up[k]&&up[k].lvl)|0)).join(','),flat(bo),Object.keys(mc).filter(k=>mc[k]).sort().join(','),Object.keys(so).filter(k=>so[k]).sort().join(','),s.best|0,flat(mw),dl.last|0,dl.buys|0].join('|');
  };
  // valeurs impossibles (hors de portée d'une partie normale)
  const plaus=s=>{
    const bad=[];try{
      const fin=v=>typeof v==='number'&&isFinite(v);
      if(!fin(+s.bank)||s.bank<0||s.bank>2e8) bad.push('argent');
      if(!fin(+s.xp)||s.xp<0||s.xp>2e9) bad.push('expérience');
      if((s.hpLvl|0)>MAX_UP||(s.hpLvl|0)<0) bad.push('vie max');
      if((s.best|0)>1000) bad.push('record');
      for(const k in (s.own||{})) if(!WEAPONS.some(w=>w.name===k)) bad.push('arme inconnue '+k);
      for(const k in (s.up||{})){const l=(s.up[k]&&s.up[k].lvl)|0;if(l<0||l>4) bad.push('amélioration '+k)}
      for(const k in (s.boost||{})){const b=BDEF[k];if(!b||s.boost[k]<0||s.boost[k]>bMax(b)) bad.push('boost '+k)}
      for(const m in (s.mapWaves||{})) for(const d in s.mapWaves[m]) if(s.mapWaves[m][d]>1000) bad.push('manches');
      if(s.daily&&s.daily.last>Date.now()+3e5) bad.push('horloge du tirage');
    }catch(e){bad.push('structure')}
    return bad;
  };
  const marker=()=>{try{return localStorage.getItem('zs_acm')}catch(e){return null}};
  const setMarker=()=>{try{localStorage.setItem('zs_acm',h53(SALT,3))}catch(e){}};
  // --- à chaque chargement : signature + plausibilité + horloge ---
  function check(s){
    const a=s.ac;let bad=false;
    if(a&&a.s){if(a.s!==sign(canon(s))){st.sig='bad';bad=true;note('Signature de la sauvegarde invalide : données modifiées hors du jeu')}else st.sig='ok'}
    else if(marker()){
      let imp=false;try{imp=localStorage.getItem('zs_acimp')==='1'}catch(e){}
      if(imp){st.sig='new';try{localStorage.removeItem('zs_acimp')}catch(e){}note('Sauvegarde importée par le jeu : nouvelle signature')}      // import fait depuis le jeu (contrôlé par le coffre) : on re-signe
      else{st.sig='bad';bad=true;note('Signature de la sauvegarde absente alors que ce navigateur en avait une')}
    }
    else st.sig='new';                                                  // première utilisation depuis l'arrivée de l'anti-triche : on accepte et on signe
    if(a&&a.f){st.sig='bad';bad=true;note('Sauvegarde déjà marquée comme modifiée')}
    const p=plaus(s);if(p.length){st.plaus='bad';bad=true;note('Valeurs impossibles : '+p.slice(0,4).join(', '))}
    const now=Date.now();
    if(a&&a.t&&now<a.t-120000){st.clock='bad';note('Horloge de l\'appareil remise en arrière')}
    if(bad){st.tampered=true;st.mpBlock='Sauvegarde modifiée : multijoueur indisponible'}
    return !bad;
  }
  function stamp(s){                                                     // appelé à chaque sauvegarde
    const prev=s.ac&&s.ac.t||0;
    const g=s.ac&&s.ac.g;
    if(st.tampered) s.ac={s:'x',t:Math.max(prev,Date.now()),v:VER,f:1,g};
    else{s.ac={s:sign(canon(s)),t:Math.max(prev,Date.now()),v:VER,g};setMarker()}
  }
  // --- surveillance pendant la partie : sauts de valeurs impossibles ---
  let sh=null;const T0=Date.now(),P0=performance.now();let lastDrift=0;
  const flagRun=why=>{if(!st.cheat){st.cheat=true;st.rt='bad';st.runReason=why;st.mpBlock='Anti-triche : valeur modifiée détectée ('+why+')';note('Triche détectée en partie : '+why)}};
  function watch(){
    try{
      if((state!=='play'&&state!=='fw')||!player||(MP&&MP.on&&MP.role==='guest')) {sh=null;return}
      const cur={m:money,x:runXp,k:kills,w:wave,hp:player.hp};
      if(sh){
        if(!isFinite(cur.m)||!isFinite(cur.x)||!isFinite(cur.hp)) flagRun('valeur non numérique');
        else if(cur.m-sh.m>20000) flagRun('argent');
        else if(cur.x-sh.x>20000) flagRun('expérience');
        else if(cur.k-sh.k>80) flagRun('éliminations');
        else if(cur.w-sh.w>1) flagRun('manche');
        else if(cur.w<sh.w&&!(cur.w===0)) flagRun('manche');
        else if(cur.m<sh.m-1e-6||cur.x<sh.x-1e-6) { /* reset de partie : accepté */ }
      }
      if(player.hp>player.maxhp+1e-6) flagRun('vie');
      if(player.maxhp>100+20*MAX_UP+1e-6) flagRun('vie max');
      if(player.maxhp>100+20*(save.hpLvl|0)+1e-6) flagRun('vie max');
      sh=cur;
    }catch(e){}
  }
  // --- 3D libre : vitesse de déplacement et cadence de tir impossibles ---
  let spdN=0,spdT=0,fireQ=[];
  function fwStep(d,max){                                               // d = distance parcourue par pas de logique ; max = distance maximale légitime
    if(d>max*2.2){const t=performance.now();if(t-spdT>6000) spdN=0;spdT=t;if(++spdN>=4) flagRun('vitesse de déplacement')}
  }
  function fwShot(minGap){                                               // minGap = délai minimal légitime entre deux tirs (ms)
    const t=performance.now();fireQ.push(t);if(fireQ.length>8) fireQ.shift();
    if(fireQ.length>=8&&(fireQ[7]-fireQ[0])/7<minGap*.35) flagRun('cadence de tir');
  }
  // --- données du jeu : les caractéristiques des armes / zombies ne doivent pas être modifiées en mémoire ---
  let DH='';
  const dataHash=()=>{try{return h53(WEAPONS.map(w=>w.name+w.dmg+'|'+w.rate+'|'+(w.pellets||1)+'|'+(w.pierce||0)+'|'+(w.range||w.reach||0)).join(';')+JSON.stringify(ZTYPES)+JSON.stringify(BOSSES.map(b=>[b.hp,b.dmg,b.sp])),21)}catch(e){return 'x'}};
  function snapData(){DH=dataHash()}
  function dataCheck(){if(DH&&dataHash()!==DH&&st.data==='ok'){st.data='bad';st.cheat=true;st.rt='bad';st.runReason='données du jeu';st.mpBlock='Anti-triche : données du jeu modifiées';note('Caractéristiques des armes ou des zombies modifiées en mémoire')}}
  // --- intégrité du code : les fonctions sensibles ne doivent pas être remplacées ---
  const FN={};
  function snapFns(){for(const n of['persist','addMoney','addXp','finishRun','endRun','applyBonus','pickCrate','buyWeapon','buyBoost','startSpin','fwShoot','fwFire','fwMeleeHit','fwSlash','fwHurt','fwDie','fwKill','fwUseBonus','fwApply','fwPickup','fwUpdate','fwmHurtP','fwmShootFor','fwmEliminate','fwmHostMsg','nmStart','nmInit','onKill','gainChar','useAmmo','dropBonus']){try{FN[n]=h53(window[n].toString(),9)}catch(e){}}}
  function codeCheck(){for(const n in FN){let h='';try{h=h53(window[n].toString(),9)}catch(e){}if(h!==FN[n]){if(st.code==='ok'){st.code='bad';st.mpBlock='Anti-triche : code du jeu modifié ('+n+')';st.cheat=true;st.runReason='code';st.rt='bad';note('Fonction modifiée : '+n)}}}}
  function clockCheck(){dataCheck();const d=Math.abs((Date.now()-T0)-(performance.now()-P0));if(d>45000&&st.clock!=='bad'){st.clock='bad';note('Horloge modifiée pendant la session')}}
  // --- multijoueur : jeton de profil (l'hôte le vérifie), reçus signés (l'invité les vérifie) ---
  const profTok=(nonce,o)=>sign('P|'+nonce+'|'+o.n+'|'+o.lvl+'|'+o.hp+'|'+o.mel+'|'+o.v+'|'+Object.keys(o.up||{}).sort().map(k=>k+':'+o.up[k]).join(','));
  const rcpt=(gid,id,w,k,m,x)=>sign('R|'+gid+'|'+id+'|'+w+'|'+k+'|'+m+'|'+x);
  const ok=()=>!st.tampered&&!st.cheat&&st.clock!=='bad';
  const why=()=>st.mpBlock||(st.clock==='bad'?'Horloge modifiée':'');
  return Object.freeze({NAME,VER,st,note,check,stamp,sign,canon,plaus,watch,fwStep,fwShot,snapData,snapFns,codeCheck,clockCheck,profTok,rcpt,ok,why,h53});
})();

// --- État ---
const SET={gore:true,fete:true,gfx:'auto',shake:true,blood:true,aim:'mouse',vol:.6,music:true,mvol:.5,lang:null,prof:'auto',lights:1,fog:1,refl:1,post:1,bloom:0,parts:2,fps:0,hz:0,anim:2,bright:.5,fc:null,gp:{dead:.25,sens:1,rumble:true,on:true,cursor:true},m3:false};   // aim : 'mouse' (visée à la souris) ou 'dir' (tir droit dans le sens du déplacement)
