// une copie de sécurité de la version précédente est gardée (les 3 dernières).
{const pv=String(save.ver||'');save.ver=GAME_VERSION;
 if(pv&&pv!==GAME_VERSION){
  try{localStorage.setItem('zs_save_pre_'+pv.replace(/[^0-9.]/g,''),localStorage.getItem(SAVE_KEY)||JSON.stringify(save));
    const ks=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.indexOf('zs_save_pre_')===0) ks.push(k)}
    ks.sort((a,b)=>parseFloat(a.slice(12))-parseFloat(b.slice(12)));while(ks.length>3) localStorage.removeItem(ks.shift())}catch(e){}
  window.__updNotice=[pv,GAME_VERSION];
 }}
const prevCleared=m=>{const i=MAPS.indexOf(m);return i>0&&!!save.mapClear[MAPS[i-1].id]};
