function recordWaves(){if(training||wave<1) return;const done=waveBreak>0?wave:wave-1,m=save.mapWaves[curMap.id]||(save.mapWaves[curMap.id]={});m[curDiff.id]=Math.max(m[curDiff.id]||0,done)}
