let bindListen=null,nearC=null;
function keyName(c){
  if(!c) return '—';
  const m={Space:'ESPACE',ArrowLeft:'←',ArrowRight:'→',ArrowUp:'↑',ArrowDown:'↓',ShiftLeft:'MAJ G',ShiftRight:'MAJ D',ControlLeft:'CTRL G',ControlRight:'CTRL D',AltLeft:'ALT G',AltRight:'ALT D',Enter:'ENTRÉE',Tab:'TAB',Backspace:'RETOUR',Semicolon:';',Comma:',',Period:'.',Slash:'/',Backslash:'\\',Quote:"'",Minus:'-',Equal:'='};
  if(m[c]) return m[c];
  if(/^Key[A-Z]$/.test(c)) return c.slice(3);
  if(/^Digit\d$/.test(c)) return c.slice(5);
  if(/^Numpad/.test(c)) return tr('Pavé').toUpperCase()+' '+c.slice(6);
  return c.toUpperCase();
}
