function captureKey(code){
  const b=bindListen;bindListen=null;
  if(code==='Escape') return;
  if(code==='Backspace'||code==='Delete'){KEYS[b.action][b.slot]='';saveKeys();return}
  for(const a in KEYS) for(let i=0;i<2;i++) if(KEYS[a][i]===code&&!(a===b.action&&i===b.slot)) KEYS[a][i]='';   // une touche = une seule action
  KEYS[b.action][b.slot]=code;saveKeys();
}
